          id: "phone",
          label: "Phone number",
          name: "phone",
          type: "tel",
          autocomplete: "tel",
          placeholder: "+1 555 123 4567",
          required: false,
          helper: "Use international format when possible, such as +1 555 123 4567."
        }
      ];

      function Field({ id, label, name, type, autocomplete, placeholder, required, helper, error }) {
