         color: var(--accent);
         font-weight: 800;
       }

       input {
         width: 100%;
         min-height: 3.25rem;
         border: 1px solid var(--border);
         border-radius: 0.9rem;
         background: rgba(8, 11, 18, 0.72);
         color: var(--text);
         font: inherit;
         padding: 0.85rem 1rem;
         transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
       }

       input::placeholder {
         color: #94a3b8;
         opacity: 1;
       }

       input:hover {
         border-color: #64748b;
         background: rgba(15, 23, 42, 0.86);
       }

       input:focus {
         border-color: var(--accent);
         outline: 3px solid rgba(56, 189, 248, 0.38);
         outline-offset: 3px;
         box-shadow: 0 0 0 1px var(--accent);
       }

       input[aria-invalid="true"] {
         border-color: var(--error);
       }

       .helper-text,
       .error-text,
       .status-message {
         margin: 0;
         font-size: 0.95rem;
       }

       .helper-text {
         color: var(--muted);
       }

       .error-text {
         color: var(--error);
         font-weight: 700;
       }

       .status-message {
         min-height: 1.5rem;
         color: #bae6fd;
       }

       button {
         min-height: 3.25rem;
         border: 0;
         border-radius: 999px;
         background: linear-gradient(135deg, var(--accent), var(--accent-strong));
         color: #03111f;
         cursor: pointer;
         font: inherit;
         font-weight: 800;
         padding: 0.9rem 1.4rem;
         transition: transform 160ms ease, box-shadow 160ms ease;
       }

       button:hover {
         box-shadow: 0 1rem 2rem rgba(14, 165, 233, 0.24);
         transform: translateY(-1px);
       }

       button:focus {
         outline: 3px solid #e0f2fe;
         outline-offset: 4px;
       }

       button:active {
         transform: translateY(0);
       }

       [hidden] {
         display: none !important;
       }

       @media (prefers-reduced-motion: reduce) {
         *,
         *::before,
         *::after {
           scroll-behavior: auto !important;
           transition-duration: 0.01ms !important;
         }
       }

       @media (forced-colors: active) {
         .support-card,
         input,
         button {
           border: 1px solid ButtonText;
         }

         button {
           forced-color-adjust: none;
           background: ButtonFace;
           color: ButtonText;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="root"></div>

     <script>
       const fields = [
         {
           id: "full-name",
           label: "Full name",
           name: "fullName",
           type: "text",
           autocomplete: "name",
           placeholder: "Alex Morgan",
           required: true,
           error: "Error: Enter your full name."
         },
         {
           id: "email",
           label: "Email address",
           name: "email",
           type: "email",
           autocomplete: "email",
           placeholder: "alex@example.com",
           required: true,
           error: "Error: Enter a valid email address, such as alex@example.com."
         },
         {
           id: "phone",
           label: "Phone number",
           name: "phone",
           type: "tel",
           autocomplete: "tel",
           placeholder: "+1 555 123 4567",
           required: false,
           helper: "Use international format when possible, such as +1 555 123 4567."
         }
       ];

       function Field({ id, label, name, type, autocomplete, placeholder, required, helper, error }) {
         const helpId = helper ? `${id}-help` : "";
         const errorId = required ? `${id}-error` : "";

         return `
           <div class="form-field">
             <label for="${id}">
               ${label}${required ? ' <span class="required-marker" aria-hidden="true">*</span>' : " (optional)"}
             </label>
             <input
               id="${id}"
               name="${name}"
               type="${type}"
               autocomplete="${autocomplete}"
               placeholder="${placeholder}"
               ${required ? "required" : ""}
               ${helpId ? `aria-describedby="${helpId}"` : ""}
               ${helpId ? `data-help-id="${helpId}"` : ""}
               ${errorId ? `data-error-id="${errorId}"` : ""}
             >
             ${helper ? `<p class="helper-text" id="${id}-help">${helper}</p>` : ""}
             ${required ? `<p class="error-text" id="${id}-error" hidden>${error}</p>` : ""}
           </div>
         `;
       }

       function SupportContactForm() {
         return `
           <main id="main-content">
             <section class="support-card" aria-labelledby="support-title">
               <p class="eyebrow">Support</p>
               <h1 id="support-title">Contact our team</h1>
               <p class="intro">Tell us how to reach you and a support specialist will follow up.</p>
               <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>
               <form id="support-form" novalidate>
                 ${fields.map(Field).join("")}
                 <p class="status-message" id="form-status" aria-live="polite"></p>
                 <button type="submit">Send request</button>
               </form>
             </section>
           </main>
         `;
       }

       function setFieldError(input, showError) {
         const helpId = input.dataset.helpId || "";
         const errorId = input.dataset.errorId || "";
         const error = errorId ? document.getElementById(errorId) : null;
         const descriptionIds = [helpId, showError ? errorId : ""].filter(Boolean);

         input.toggleAttribute("aria-invalid", showError);
         input.toggleAttribute("aria-errormessage", showError && Boolean(errorId));
         if (showError && errorId) {
           input.setAttribute("aria-errormessage", errorId);
         }
         if (descriptionIds.length) {
           input.setAttribute("aria-describedby", descriptionIds.join(" "));
         } else {
           input.removeAttribute("aria-describedby");
         }
         if (error) {
           error.hidden = !showError;
         }
       }

       function initializeForm() {
         const form = document.getElementById("support-form");
         const status = document.getElementById("form-status");
         const requiredInputs = Array.from(form.querySelectorAll("[required]"));

         requiredInputs.forEach((input) => {
           input.addEventListener("input", () => {
             if (input.checkValidity()) {
               setFieldError(input, false);
             }
           });
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           let firstInvalid = null;

           requiredInputs.forEach((input) => {
             const isInvalid = !input.checkValidity();
             setFieldError(input, isInvalid);
             if (isInvalid && !firstInvalid) {
               firstInvalid = input;
             }
           });

           if (firstInvalid) {
             status.textContent = "Please fix the highlighted fields.";
             firstInvalid.focus();
             return;
           }

           status.textContent = "Thanks. Your support request is ready to send.";
           form.reset();
         });
       }

       document.getElementById("root").innerHTML = SupportContactForm();
       initializeForm();
     </script>
   </body>
 </html>

')
